<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('pelamar');$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT l.*,d.nama_divisi FROM lowongan l JOIN divisi d ON d.id_divisi=l.id_divisi WHERE l.id_lowongan=? AND l.status='Dipublikasikan'");$s->execute([$id]);$l=$s->fetch();if(!$l)die('Lowongan tidak ditemukan.');$q=$pdo->prepare('SELECT * FROM tahapan_seleksi WHERE id_lowongan=? ORDER BY urutan');$q->execute([$id]);$steps=$q->fetchAll();$q=$pdo->prepare('SELECT id_lamaran FROM lamaran WHERE id_lowongan=? AND id_pelamar=?');$q->execute([$id,user()['id_pelamar']]);$applied=$q->fetch();page_header('Detail Lowongan');?><div class="card"><h2><?=e($l['judul_lowongan'])?></h2><p><strong>Divisi:</strong> <?=e($l['nama_divisi'])?></p><p><strong>Kebutuhan:</strong> <?=e($l['jumlah_kebutuhan'])?></p><p><strong>Deadline:</strong> <?=e($l['deadline']?:'-')?></p><h3>Job Description</h3><p><?=nl2br(e($l['job_description']))?></p><h3>Job Specification</h3><p><?=nl2br(e($l['job_specification']))?></p><h3>Tahapan Seleksi</h3><ol><?php foreach($steps as $x):?><li><?=e($x['nama_tahapan'])?> — <?=e($x['deskripsi'])?></li><?php endforeach;?></ol><?php if($applied):?><p class="badge">Kamu sudah melamar posisi ini.</p><?php else:?><a class="btn" href="apply.php?id=<?=$id?>">Apply</a><?php endif;?></div><?php page_footer();
